<template>
  <div class="flex flex-col gap-2 items-center w-full">
    <AppEmpty v-if="!imageUrl" variant="table" subject="signature preview" />
    <div v-else class="w-full h-auto flex justify-center items-center relative">
      <AppLoader v-if="loading" variant="inline" />
      <AppError
        v-else-if="error"
        variant="table"
        title="Failed to load signature image"
        :action-text="null"
        message=""
      />
      <img
        v-show="!loading && !error"
        :src="imageUrl"
        alt="signature preview"
        class="w-full h-auto"
        @load="loading = false"
        @error="
          () => {
            loading = false;
            error = true;
          }
        "
      />
    </div>
    <NuxtLink
      v-if="ballotPageId"
      :to="{
        name: 'verification-ballots-pages-id',
        params: { id: ballotPageId },
        ...(signatureId && { query: { signature_id: signatureId } }),
      }"
    >
      <Button variant="outline">{{ buttonLabel }}</Button>
    </NuxtLink>
  </div>
</template>

<script setup lang="ts">
interface Props {
  imageUrl?: string | null;
  ballotPageId?: string | null;
  signatureId?: string | null;
  buttonLabel?: string;
}

defineProps<Props>();

const loading = ref<boolean>(true);
const error = ref<boolean>(false);

onUnmounted(() => {
  loading.value = true;
  error.value = false;
});
</script>
